package org.apache.commons.compress.archivers.cpio;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.nio.ByteBuffer;
import java.util.*;
import java.util.HashMap;
import org than.junit.Test;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.apache.commons.compress.utils.CharsetNames;
import org.junit.*;
import org.junit.Assert;
import static org.junit.Assert.*;
import static org.junit.Assert.assertThrows;

public class CpioArchiveOutputStream_CpioArchiveOutputStream_TriageGen2Test {

    private static final short FORMAT_NEW = CpioArchiveOutputStream.FORMAT_NEW;
    private static final short FORMAT_NEW_CRC = CpioArchiveOutputStream.FORMAT_NEW_CRC;
    private static final short FORMAT_OLD_ASCII = CpioArchiveOutputStream.FORMAT_OLD_ASCII;
    private static final short FORMAT_OLD_BINARY = CpioArchiveOutputStream.FORMAT_OLD_BINARY;
    private static final short INVALID_FORMAT = 999;

    @Test
    public void testConstructorWithFormatNew() throws IOException {
        OutputStream out = new ByteArrayOutputStream();
        CpioArchiveOutputStream caos = new CpioArchiveOutputStream(out, FORMAT_NEW, 1024, "UTF-8");
        Assert.assertNotNull(caos);
        caos.close();
    }

    @Test
    public void testConstructorWithFormatNewCrc() throws IOException {
        OutputStream out = new ByteArrayOutputStream();
        CpioArchiveOutputStream caos = new CpioArchiveOutputStream(out, FORMAT_NEW_CRC, 1024, "UTF-8");
        Assert.assertNotNull(caos);
        caos.close();
    }

    @Test
    public void testConstructorWithFormatOldAscii() throws IOException {
        OutputStream out = new ByteArrayOutputStream();
        CpioArchiveOutputStream caos = new CpioArchiveOutputStream(out, FORMAT_OLD_ASCII, 1024, "UTF-8");
        Assert.assertNotNull(caos);
        caos.close();
    }

    @Test
    public void testConstructorWithFormatOldBinary() throws IOException {
        OutputStream out = new ByteArrayOutputStream();
        CpioArchiveOutputStream caos = new CpioArchiveOutputStream(out, FORMAT_OLD_BINARY, 1024, "UTF-8");
        Assert.assertNotNull(caos);
        caos.close();
    }

    @Test
    public void testConstructorWithInvalidFormatThrowsException() {
        OutputStream out = new ByteArrayOutputStream();
        assertThrows(IllegalArgumentException.class, () -> {
            new CpioArchiveOutputStream(out, INVALID_FORMAT, 1024, "UTF-8");
        });
    }

    @Test
    public void testConstructorWithNullEncoding() throws IOException {
        // Testing how ZipEncodingHelper handles null to ensure line coverage
        OutputStream out = new ByteArrayOutputStream();
        CpioArchiveOutputStream caos = new CpioArchiveOutputStream(out, FORMAT_NEW, 1024, null);
        Assert.assertNotNull(caos);
        caos.close();
    }
}
